// Test of mgc_ffn_swiglu, generated by mgc from ffn_swiglu.mgc: do not edit, re-run mgc/mgcc.py.

#include <stdint.h>

#include "mgc_ffn_swiglu.h"
#include "test.h"

#include "tile.h"
#include "fsync.h"
#include "eventunit.h"

int main(void)
{
    uint32_t hartid = get_hartid();

    mgc_ffn_swiglu(x_inp,
                   wg_inp,
                   wu_inp,
                   wd_inp,
                   res_inp,
                   h_l2,
                   y_out,
                   SEQ_LENGTH,
                   EMBED_SIZE,
                   FFN_SIZE,
                   FFN_CI,
                   FFN_KB_E,
                   FFN_KB_I);

    /* once every tile has finished, each tile checks its share of the rows */
    fsync_init();
    eu_fsync_init(0);
    fsync_sync_global();
    eu_fsync_wait(WFE);

    uint32_t share  = (SEQ_LENGTH + NUM_HARTS - 1) / NUM_HARTS;
    uint32_t r_end  = (hartid + 1) * share < SEQ_LENGTH ? (hartid + 1) * share : SEQ_LENGTH;
    uint32_t errors = 0;
    uint16_t computed, expected, diff;
    for (uint32_t i = hartid * share; i < r_end; i++) {
        for (uint32_t j = 0; j < EMBED_SIZE; j++) {
            computed = *(volatile uint16_t *)(y_out + (i * EMBED_SIZE + j));
            expected = *(volatile uint16_t *)(y_gold + (i * EMBED_SIZE + j));
            diff     = (computed > expected) ? (computed - expected) : (expected - computed);
            if (diff > 0x0011) {
#if EVAL == 1
                printf("Error detected at coordinates[%d][%d]: y_out=%x y_gold=%x\n",
                       i,
                       j,
                       *(volatile uint16_t *)(y_out + (i * EMBED_SIZE + j)),
                       *(volatile uint16_t *)(y_gold + (i * EMBED_SIZE + j)));
#endif
                errors++;
            }
        }
    }
    printf("TILE %d: Number of errors: %d\n", hartid, errors);

    return errors;
}
